/* The translator's shader capabilities (section 13, SHADER CAPABILITIES):
 * subgroups, robustness, integer dot products, the memory model, workgroup
 * memory initialization, float controls, expect/assume and the fragment
 * leftovers (interpolateAt*, demote, terminate in called functions). Each
 * shader is translated, compiled by Metal, run on real data and compared
 * with a CPU reference.
 *
 * Shaders: GLSL in the comment above each array, compiled with
 *   glslangValidator -V --target-env vulkan1.3
 * (instructions GLSL has no syntax for through GL_EXT_spirv_intrinsics) and
 * *_opt variants additionally with spirv-opt -O. */
