 *         outb.o[b0 + 10u] = subgroupAll(v > -1000) ? 1u : 0u;
 *         outb.o[b0 + 11u] = subgroupAll(v > 0) ? 1u : 0u;
 *         outb.o[b0 + 12u] = subgroupAny(v > 900) ? 1u : 0u;
 *         outb.o[b0 + 13u] = subgroupAllEqual(v) ? 1u : 0u;
