 *     outb.o[i * 8u + 3u] = floatBitsToUint(uu.x + uu.w);
 *     wb.w[idx] = i + 1000u;
 *     outb.o[i * 8u + 4u] = atomicAdd(wb.w[idx + 64], 1u);
