 *     outb.o[12] = floatBitsToUint(z * nz);
 *     outb.o[13] = floatBitsToUint((nz + z) - z);
 *     hb.h[0] = float16_t(one + tiny * 8192.0);
 *     hb.h[1] = float16_t(one + tiny * 8192.0 * 3.0);
 *     hb.h[2] = float16_t(nz);
 *     hb.h[3] = float16_t(inf);
 *     hb.h[4] = float16_t(nan);
 *     hb.h[5] = float16_t(one * 65520.0);
 *     hb.h[6] = float16_t(one * 65519.0);
