/*
 * #version 450
 * #extension GL_EXT_spirv_intrinsics : require
 * #define VP(id_) spirv_instruction(extensions = ["SPV_KHR_variable_pointers"], capabilities = [4441, 4442], id = id_)
 * #define SBPTR spirv_type(extensions = ["SPV_KHR_variable_pointers"], capabilities = [4441], id = 32, 12, uint)
 * #define WGPTR spirv_type(extensions = ["SPV_KHR_variable_pointers"], capabilities = [4442], id = 32, 4, uint)
 * VP(169) SBPTR select_sb(bool c, spirv_by_reference uint a, spirv_by_reference uint b);
 * VP(169) SBPTR select_sbp(bool c, SBPTR a, SBPTR b);
 * VP(169) WGPTR select_wg(bool c, spirv_by_reference uint a, spirv_by_reference uint b);
 * VP(61) uint load_sb(SBPTR p);
 * VP(62) void store_sb(SBPTR p, uint v);
 * VP(61) uint load_wg(WGPTR p);
 * VP(401) bool ptr_equal(SBPTR a, SBPTR b);
 * VP(402) bool ptr_not_equal(WGPTR a, WGPTR b);
 * layout(local_size_x = 64) in;
 * layout(std430, binding = 0) readonly buffer A { uint a[]; };
 * layout(std430, binding = 1) readonly buffer B { uint b[]; };
 * layout(std430, binding = 2) buffer C { uint c[]; };
 * layout(std430, binding = 3) writeonly buffer Out { uint o[]; };
 * shared uint wa[64], wb[64];
 * SBPTR pick(uint i)
 * {
 *     return select_sb((i & 1u) != 0u, a[i], b[i]);
 * }
 * uint deref(SBPTR p)
 * {
 *     return load_sb(p);
 * }
 * void main()
 * {
 *     uint i = gl_LocalInvocationIndex;
 *     wa[i] = i * 10u;
 *     wb[i] = i * 100u;
 *     barrier();
 *     SBPTR p = pick(i);
 *     uint v = deref(p);
 *     SBPTR q = select_sb(false, a[0], c[2u * i]);
 *     if (v > 50u)
 *         q = select_sb(true, c[2u * i + 1u], b[0]);
 *     store_sb(q, v + 1000u);
 *     WGPTR w = select_wg(i < 32u, wa[i], wb[i ^ 1u]);
 *     o[i * 4u + 0u] = v;
 *     o[i * 4u + 1u] = load_wg(w);
 *     o[i * 4u + 2u] = (ptr_equal(p, select_sbp(true, p, q)) ? 1u : 0u) |
 *                      (ptr_not_equal(w, select_wg(false, wa[0], wb[i ^ 1u])) ? 2u : 0u);
 *     o[i * 4u + 3u] = load_sb(select_sbp(v > 50u, q, p));
 * }
 */
