/* ==========================================================================
 * Helpers
 * ========================================================================== */

/* Mismatches of one test: the first few are printed, the test then fails. */
static int bad;
#define EXPECT(cond, ...)                                       \
    do {                                                        \
        if (!(cond) && bad++ < 8) {                             \
            fprintf(stderr, "  mismatch: ");                    \
            fprintf(stderr, __VA_ARGS__);                       \
            fputc('\n', stderr);                                \
        }                                                       \
    } while (0)

static struct mt_binding bind(uint32_t set, uint32_t binding, struct mt_buffer *buf)
{
    struct mt_binding b;
    memset(&b, 0, sizeof(b));
    b.set = set;
    b.binding = binding;
    b.buf = buf;
    return b;
}

/* Translates and compiles count words: the pipeline (retained), NULL on
 * failure; on success res must be freed. */
static id build(const uint32_t *words, size_t count, const struct pvk_msl_options *options, struct pvk_msl_result *res)
{
    id pso;
    if (!mt_translate(words, count, options, res))
        return NULL;
    pso = mt_pipeline(res);
    if (!pso)
        pvk_msl_result_free(res);
    return pso;
}

static uint32_t f2u(float f)
{
    uint32_t u;
    memcpy(&u, &f, 4);
    return u;
}

static float u2f(uint32_t u)
{
    float f;
    memcpy(&f, &u, 4);
    return f;
}

/* ==========================================================================
 * Subgroups
 *
 * Two SIMD-groups of 32 lanes per workgroup, each partially active: the
 * shaders branch on an input mask, so only the masked lanes take part.
 * Results from lanes Vulkan leaves undefined (reads of inactive lanes) are
 * not compared; inactive lanes must write nothing.
 * ========================================================================== */

static const uint32_t sg_masks[2] = { 0x5a5a5a5au, 0xfffff00fu };

struct sg_input {
    uint32_t mask[2];
    uint32_t d[2];
    int32_t vals[64];
};

static void sg_init(struct sg_input *in, uint32_t d0, uint32_t d1)
{
    uint32_t i;
    in->mask[0] = sg_masks[0];
    in->mask[1] = sg_masks[1];
    in->d[0] = d0;
    in->d[1] = d1;
    for (i = 0; i < 64; i++)
        in->vals[i] = (int32_t)((i * 7919u + 13u) % 2001u) - 1000;
}

static bool sg_active(uint32_t s, uint32_t lane)
{
    return lane < 32 && ((sg_masks[s] >> lane) & 1u);
}

static uint32_t popcount32(uint32_t v)
{
    uint32_t n = 0;
    for (; v; v &= v - 1)
        n++;
    return n;
}

/* Runs a one-workgroup subgroup test shader: input binding 0, output binding 1. */
static bool sg_run(const uint32_t *words, size_t count, const struct sg_input *in, uint32_t *out, size_t out_words)
{
    struct pvk_msl_result res;
    struct mt_buffer ib, ob;
    struct mt_binding b[2];
    id pso;
    bool ok;
    if (!mt_translate(words, count, NULL, &res))
        return false;
    pso = mt_pipeline(&res);
    if (!pso) {
        pvk_msl_result_free(&res);
        return false;
    }
    ib = mt_buffer(sizeof(*in), in, sizeof(*in));
    ob = mt_buffer(out_words * 4, NULL, 0);
    b[0] = bind(0, 0, &ib);
    b[1] = bind(0, 1, &ob);
    ok = mt_dispatch(pso, &res, b, 2, NULL, 0, 1, 1, 1);
    memcpy(out, ob.data, out_words * 4);
    mt_buffer_free(&ib);
    mt_buffer_free(&ob);
    pvk_release(pso);
    pvk_msl_result_free(&res);
    return ok;
}

static void check_sg_ballot(const uint32_t *words, size_t count)
{
    struct sg_input in;
    uint32_t out[64 * 32], s, l, k;
    sg_init(&in, 1, 0);
    REQUIRE(sg_run(words, count, &in, out, 64 * 32));
    bad = 0;
    for (s = 0; s < 2; s++) {
        uint32_t m = sg_masks[s], ball = 0, first = 32, all_pos = 1, all_ge = 1, any_big = 0, eq = 1, eq_sign = 1;
        int32_t v0 = 0;
        for (l = 0; l < 32; l++) {
            int32_t v = in.vals[32 * s + l];
            if (!sg_active(s, l))
                continue;
            if (first == 32) {
                first = l;
                v0 = v;
            }
            ball |= (v > 50 ? 1u : 0u) << l;
            all_pos &= v > 0;
            all_ge &= v > -1000;
            any_big |= v > 900;
            eq &= v == v0;
            eq_sign &= (v & 0x10000) == (v0 & 0x10000);
        }
        for (l = 0; l < 32; l++) {
            const uint32_t *o = out + (32 * s + l) * 32;
            int32_t v = in.vals[32 * s + l];
            uint32_t want[32];
            memset(want, 0, sizeof(want));
            want[0] = 32;
            want[1] = l;
            want[2] = s;
            want[3] = 2;
            want[4] = 1u << l;
            want[5] = 0xffffffffu << l;
            want[6] = 0xfffffffeu << l;
            want[7] = (uint32_t)((2ull << l) - 1);
            want[8] = (1u << l) - 1;
            if (sg_active(s, l)) {
                want[9] = l == first;
                want[10] = all_ge;
                want[11] = all_pos;
                want[12] = any_big;
                want[13] = eq;
                want[14] = eq_sign;
                want[15] = ball;
                want[16] = 0;
                want[17] = popcount32(ball);
                want[18] = popcount32(ball & (uint32_t)((2ull << l) - 1));
                want[19] = popcount32(ball & ((1u << l) - 1));
                for (k = 0; k < 32 && !((ball >> k) & 1u); k++)
                    ;
                want[20] = k;
                for (k = 31; k > 0 && !((ball >> k) & 1u); k--)
                    ;
                want[21] = k;
                want[22] = (ball >> l) & 1u;
                want[23] = (ball >> 9) & 1u;
                want[24] = (ball >> (l ^ 1)) & 1u;
                want[25] = (uint32_t)v0;
                want[26] = (uint32_t)in.vals[32 * s + 3];
                want[27] = (uint32_t)in.vals[32 * s + 1];
                want[28] = v0 > 0;
                want[30] = m;
                want[31] = 7;
                {
                    uint32_t j, pos = 0, neg = 0;
                    for (j = 0; j < 32; j++)
                        if (sg_active(s, j)) {
                            pos |= in.vals[32 * s + j] > 0;
                            neg |= in.vals[32 * s + j] <= 0;
                        }
                    want[29] = !(pos && neg);
                }
            }
            (void)v;
            for (k = 0; k < 32; k++)
                EXPECT(o[k] == want[k], "subgroup %u lane %u result %u: %u (0x%x), want %u (0x%x)", s, l, k, o[k], o[k],
                       want[k], want[k]);
        }
    }
    CHECK(bad == 0);
}

static void test_subgroup_ballot(void)
{
    check_sg_ballot(spv_sg_ballot, PVK_ARRAY_SIZE(spv_sg_ballot));
}

static void test_subgroup_ballot_opt(void)
{
    check_sg_ballot(spv_sg_ballot_opt, PVK_ARRAY_SIZE(spv_sg_ballot_opt));
}

static void check_sg_shuffle(const uint32_t *words, size_t count)
{
    struct sg_input in;
    uint32_t out[64 * 16], s, l, k;
    sg_init(&in, 6, 2);
    REQUIRE(sg_run(words, count, &in, out, 64 * 16));
    bad = 0;
    for (s = 0; s < 2; s++) {
        for (l = 0; l < 32; l++) {
            const uint32_t *o = out + (32 * s + l) * 16;
            int src[16];
            if (!sg_active(s, l)) {
                for (k = 0; k < 16; k++)
                    EXPECT(o[k] == 0, "inactive lane %u of subgroup %u wrote result %u", l, s, k);
                continue;
            }
            src[0] = (int)((l * 5 + 3) & 31);
            src[1] = (int)(l ^ 1);
            src[2] = (int)(l ^ 6);
            src[3] = (int)l - 2;
            src[4] = (int)l - 2;
            src[5] = (int)l + 3;
            src[6] = (int)l + 2;
            src[7] = (int)((l + 5) & 31);
            src[8] = (int)((l & ~3u) | ((l + 1) & 3));
            src[9] = (int)((l & ~7u) | ((l + 2) & 7));
            src[10] = (int)(l ^ 1);
            src[11] = (int)(l ^ 2);
            src[12] = (int)(l ^ 3);
            src[13] = (int)((l & ~3u) | 2);
            src[14] = (int)(l ^ 2);
            src[15] = (int)(l ^ 4);
            for (k = 0; k < 16; k++) {
                int32_t sv;
                uint32_t want;
                if (src[k] < 0 || !sg_active(s, (uint32_t)src[k]))
                    continue; /* undefined in Vulkan */
                sv = in.vals[32 * s + (uint32_t)src[k]];
                want = k == 14 ? (uint32_t)(-sv) : k == 15 ? (uint32_t)(sv > 0) : (uint32_t)sv;
                EXPECT(o[k] == want, "subgroup %u lane %u result %u: %d, want %d (lane %d)", s, l, k, (int)o[k], (int)want,
                       src[k]);
            }
        }
    }
    CHECK(bad == 0);
}

static void test_subgroup_shuffle(void)
{
    check_sg_shuffle(spv_sg_shuffle, PVK_ARRAY_SIZE(spv_sg_shuffle));
}

static void test_subgroup_shuffle_opt(void)
{
    check_sg_shuffle(spv_sg_shuffle_opt, PVK_ARRAY_SIZE(spv_sg_shuffle_opt));
}

/* The active lanes before (exclusive), up to (inclusive) or all of lane l. */
enum { SG_REDUCE, SG_INCL, SG_EXCL };
static bool sg_in_range(uint32_t s, uint32_t j, uint32_t l, int mode)
{
    return sg_active(s, j) && (mode == SG_REDUCE || (mode == SG_INCL ? j <= l : j < l));
}

static void check_sg_arith(const uint32_t *words, size_t count)
{
    struct sg_input in;
    uint32_t out[64 * 48], s, l, k, j;
    int mode;
    sg_init(&in, 0, 0);
    REQUIRE(sg_run(words, count, &in, out, 64 * 48));
    bad = 0;
    for (s = 0; s < 2; s++) {
        for (l = 0; l < 32; l++) {
            const uint32_t *o = out + (32 * s + l) * 48;
            uint32_t want[48];
            if (!sg_active(s, l)) {
                for (k = 0; k < 48; k++)
                    EXPECT(o[k] == 0, "inactive lane %u of subgroup %u wrote result %u", l, s, k);
                continue;
            }
            for (mode = 0; mode < 3; mode++) {
                int32_t smin = INT32_MAX, smax = INT32_MIN;
                uint32_t add = 0, mul = 1, umin = UINT32_MAX, umax = 0, and_ = UINT32_MAX, or_ = 0, xor_ = 0;
                float fadd = 0.0f, fmul = 1.0f, fmin_ = INFINITY, fmax_ = -INFINITY;
                bool land = true, lor = false, lxor = false;
                for (j = 0; j < 32; j++) {
                    int32_t v;
                    uint32_t u;
                    float f, g;
                    bool p;
                    if (!sg_in_range(s, j, l, mode))
                        continue;
                    v = in.vals[32 * s + j];
                    u = (uint32_t)v * 2654435761u;
                    f = (float)(abs(v) % 64);
                    g = (v & 1) ? 2.0f : ((v & 2) ? 0.5f : -1.0f);
                    p = (v & 4) != 0;
                    add += (uint32_t)v;
                    mul *= u;
                    smin = v < smin ? v : smin;
                    smax = v > smax ? v : smax;
                    umin = u < umin ? u : umin;
                    umax = u > umax ? u : umax;
                    and_ &= u;
                    or_ |= u;
                    xor_ ^= u;
                    fadd += f;
                    fmul *= g;
                    fmin_ = f < fmin_ ? f : fmin_;
                    fmax_ = f > fmax_ ? f : fmax_;
                    land = land && p;
                    lor = lor || p;
                    lxor = lxor != p;
                }
                want[0 + mode] = add;
                want[3 + mode] = mul;
                want[6 + mode] = (uint32_t)smin;
                want[9 + mode] = umin;
                want[12 + mode] = (uint32_t)smax;
                want[15 + mode] = umax;
                want[18 + mode] = and_;
                want[21 + mode] = or_;
                want[24 + mode] = xor_;
                want[27 + mode] = f2u(fadd);
                want[30 + mode] = f2u(fmul);
                want[33 + mode] = f2u(fmin_);
                want[36 + mode] = f2u(fmax_);
                want[39 + mode] = land;
                want[42 + mode] = lor;
                want[45 + mode] = lxor;
            }
            for (k = 0; k < 48; k++) /* (the first lane's exclusive float sum may be -0: also an identity of +) */
                EXPECT(o[k] == want[k] || (k == 29 && u2f(o[k]) == u2f(want[k])), "subgroup %u lane %u result %u: 0x%08x (%g), want 0x%08x (%g)", s, l, k, o[k],
                       (double)u2f(o[k]), want[k], (double)u2f(want[k]));
        }
    }
    CHECK(bad == 0);
}

static void test_subgroup_arithmetic(void)
{
    check_sg_arith(spv_sg_arith, PVK_ARRAY_SIZE(spv_sg_arith));
}

static void test_subgroup_arithmetic_opt(void)
{
    check_sg_arith(spv_sg_arith_opt, PVK_ARRAY_SIZE(spv_sg_arith_opt));
}

static void test_subgroup_types(void)
{
    struct sg_input in;
    uint32_t out[64 * 24], s, l, k, j;
    sg_init(&in, 0, 0);
    REQUIRE(sg_run(spv_sg_types, PVK_ARRAY_SIZE(spv_sg_types), &in, out, 64 * 24));
    bad = 0;
    for (s = 0; s < 2; s++) {
        int32_t v0 = 0;
        for (j = 0; j < 32 && !sg_active(s, j); j++)
            ;
        v0 = in.vals[32 * s + j];
        for (l = 0; l < 32; l++) {
            const uint32_t *o = out + (32 * s + l) * 24;
            uint32_t want[24], sum0 = 0, sum1 = 0, x0 = 0, x1 = 0, x2 = 0, umin16 = 0xffff, bor = 0;
            int32_t max0 = INT32_MIN, max1 = INT32_MIN, smax16 = INT16_MIN, cmin = 127;
            int8_t csum = 0;
            int16_t smul = 1;
            uint64_t lsum = 0, lincl = 0, ulmax = 0;
            float hsum = 0.0f, hmax = -INFINITY;
            if (!sg_active(s, l)) {
                for (k = 0; k < 24; k++)
                    EXPECT(o[k] == 0, "inactive lane %u of subgroup %u wrote result %u", l, s, k);
                continue;
            }
            for (j = 0; j < 32; j++) {
                int32_t v = in.vals[32 * s + j];
                if (!sg_active(s, j))
                    continue;
                sum0 += (uint32_t)v;
                sum1 += (uint32_t)(v * 3 - 7);
                csum = (int8_t)(uint8_t)((uint8_t)csum + (uint8_t)(int8_t)v);
                smax16 = (int16_t)(v * 37) > smax16 ? (int16_t)(v * 37) : smax16;
                lsum += (uint64_t)((int64_t)v * 0x100000001ll);
                hsum += (float)(abs(v) % 32);
                x0 ^= (uint32_t)v;
                x1 ^= (uint32_t)v << 8;
                x2 ^= (uint32_t)v ^ 0x55u;
                if (j <= l) {
                    max0 = v > max0 ? v : max0;
                    max1 = v * 3 - 7 > max1 ? v * 3 - 7 : max1;
                    smul = (int16_t)(uint16_t)((uint32_t)(uint16_t)smul * (uint32_t)(uint16_t)(int16_t)(v * 37));
                    umin16 = (uint32_t)(v + 3000) < umin16 ? (uint32_t)(v + 3000) : umin16;
                    lincl += (uint64_t)((int64_t)v * 0x100000001ll);
                    hmax = (float)(abs(v) % 32) > hmax ? (float)(abs(v) % 32) : hmax;
                    bor |= ((v & 1) ? 1u : 0u) | ((v & 8) ? 2u : 0u);
                }
                if (j < l) {
                    cmin = (int8_t)v < cmin ? (int8_t)v : cmin;
                    ulmax = ((uint64_t)(uint32_t)v << 20) > ulmax ? ((uint64_t)(uint32_t)v << 20) : ulmax;
                }
            }
            want[0] = sum0;
            want[1] = sum1;
            want[2] = (uint32_t)max0;
            want[3] = (uint32_t)max1;
            want[4] = (uint32_t)(int32_t)csum;
            want[5] = (uint32_t)cmin;
            want[6] = (uint32_t)(int32_t)smul;
            want[7] = (uint32_t)smax16;
            want[8] = umin16;
            want[9] = (uint32_t)lsum;
            want[10] = (uint32_t)(lsum >> 32);
            want[11] = (uint32_t)lincl;
            want[12] = (uint32_t)(lincl >> 32);
            {
                uint64_t ub = ((uint64_t)(uint32_t)v0 << 20) + ((uint64_t)(uint32_t)in.vals[32 * s + (l ^ 1)] << 20);
                want[13] = (uint32_t)ub;
                want[14] = (uint32_t)(ub >> 32);
            }
            want[15] = (uint32_t)ulmax;
            want[16] = (uint32_t)(ulmax >> 32);
            want[17] = (uint32_t)hsum;
            want[18] = (uint32_t)hmax;
            want[19] = bor;
            want[20] = x0;
            want[21] = x1;
            want[22] = x2;
            want[23] = (uint32_t)(int32_t)(int8_t)in.vals[32 * s + (l ^ 3)];
            for (k = 0; k < 24; k++) {
                if ((k == 13 || k == 14) && !sg_active(s, l ^ 1))
                    continue;
                if (k == 23 && !sg_active(s, l ^ 3))
                    continue;
                EXPECT(o[k] == want[k], "subgroup %u lane %u result %u: 0x%08x, want 0x%08x", s, l, k, o[k], want[k]);
            }
        }
    }
    CHECK(bad == 0);
}

/* ==========================================================================
 * Robustness
 *
 * Buffers are bound with descriptor ranges smaller than their Metal buffers,
 * which hold a sentinel around the range: indices below and past the range
 * must read zero (also a vector that straddles the end, while components
 * inside it read their values), and writes and atomics there must change
 * nothing. Images: texels, levels, layers and texel buffer elements outside
 * the image read zero, writes and atomics there are discarded.
 * ========================================================================== */

#define SENTINEL 0x5e5e5e5eu

static struct pvk_msl_options robust_options(void)
{
    struct pvk_msl_options o;
    memset(&o, 0, sizeof(o));
    o.robust_storage_buffers = true;
    o.robust_uniform_buffers = true;
    o.robust_images = true;
    return o;
}

static void fill_u32(void *base, size_t from, size_t to, uint32_t v)
{
    size_t i;
    for (i = from; i + 4 <= to; i += 4)
        memcpy((char *)base + i, &v, 4);
}

static float rb_mat(int e, int r, int c)
{
    return (float)(e * 100 + r * 10 + c);
}

/* A word of the data buffer at offset off of its descriptor's range. */
static uint32_t rb_word(const struct mt_buffer *data, int off)
{
    return ((const uint32_t *)data->data)[(256 + off) / 4];
}

static void check_robust_buffers(const uint32_t *words, size_t count)
{
    struct pvk_msl_options opt = robust_options();
    struct pvk_msl_result res;
    struct mt_buffer data, ub, out, wb, mb;
    struct mt_binding b[5];
    int32_t base = -8;
    uint32_t *o, *w, i, k, c;
    float *m;
    id pso;

    pso = build(words, count, &opt, &res);
    REQUIRE(pso);
    data = mt_buffer(4096, NULL, 0);
    fill_u32(data.data, 0, 4096, SENTINEL);
    for (k = 0; k < 21; k++) /* v[k] at 256 + 16 + 16k; the range ends inside v[20] */
        for (c = 0; c < 4; c++)
            if (16 + 16 * k + 4 * c < 344)
                ((uint32_t *)data.data)[(256 + 16 + 16 * k + 4 * c) / 4] = (k * 4 + c + 1) * 3;
    ub = mt_buffer(2048, NULL, 0);
    fill_u32(ub.data, 0, 2048, f2u(1.0e9f));
    for (k = 0; k < 30; k++)
        for (c = 0; c < 4; c++)
            ((float *)ub.data)[(512 + 16 * k) / 4 + c] = (float)k + 0.25f * (float)c;
    out = mt_buffer(64 * 8 * 4, NULL, 0);
    wb = mt_buffer(4096, NULL, 0);
    fill_u32(wb.data, 0, 4096, SENTINEL);
    for (k = 0; k < 100; k++)
        ((uint32_t *)wb.data)[1024 / 4 + k] = k * 10;
    mb = mt_buffer(16384, NULL, 0);
    fill_u32(mb.data, 0, 16384, f2u(-7.0f));
    m = mb.data;
    for (k = 0; k < 220; k++) /* row-major mat3: rows 16 bytes apart */
        for (c = 0; c < 9; c++)
            m[(48 * k + 16 * (c / 3) + 4 * (c % 3)) / 4] = rb_mat((int)k, (int)(c / 3), (int)(c % 3));
    b[0] = bind(0, 0, &data);
    b[0].offset = 256;
    b[0].range = 344;
    b[1] = bind(0, 1, &ub);
    b[1].offset = 512;
    b[1].range = 480;
    b[2] = bind(0, 2, &out);
    b[3] = bind(0, 3, &wb);
    b[3].offset = 1024;
    b[3].range = 400;
    b[4] = bind(0, 4, &mb);
    b[4].range = 220 * 48;
    CHECK(mt_dispatch(pso, &res, b, 5, &base, 4, 1, 1, 1));
    o = out.data;
    w = wb.data;
    bad = 0;
    for (i = 0; i < 64; i++) {
        int idx = (int)i + base;
        uint32_t want[8], cc = i & 3;
        memset(want, 0, sizeof(want));
        /* (v[-1] is the range's first 16 bytes: in bounds) */
        if (16 + 16 * idx >= 0 && 16 + 16 * idx + 16 <= 344)
            for (c = 0; c < 4; c++)
                want[0] += rb_word(&data, 16 + 16 * idx + 4 * (int)c);
        if (16 + 16 * idx >= 0 && 16 + 16 * idx + 12 <= 344)
            want[1] = rb_word(&data, 16 + 16 * idx + 8);
        if (16 + 16 * idx >= 0 && 16 + 16 * idx + 4 * (int)cc + 4 <= 344)
            want[2] = rb_word(&data, 16 + 16 * idx + 4 * (int)cc);
        want[3] = f2u(idx >= 0 && idx < 30 ? (float)idx + (float)idx + 0.75f : 0.0f);
        if (idx + 64 >= 0 && idx + 64 < 100)
            want[4] = (uint32_t)(idx + 64) * 10;
        want[5] = 20;
        want[6] = f2u(idx >= 0 && idx < 220 ? rb_mat(idx, 0, 0) + rb_mat(idx, 2, 1) : 0.0f);
        for (k = 0; k < 8; k++)
            EXPECT(o[i * 8 + k] == want[k], "thread %u (index %d) result %u: 0x%08x, want 0x%08x", i, idx, k, o[i * 8 + k],
                   want[k]);
    }
    for (k = 0; k < 1024; k++) { /* writes and atomics: only inside the range */
        uint32_t want = SENTINEL;
        if (k >= 256 && k < 356) {
            uint32_t e = k - 256;
            want = e < 56 ? 1000 + e + 8 : e * 10 + 1;
        }
        EXPECT(w[k] == want, "W word %u: 0x%08x, want 0x%08x", k, w[k], want);
    }
    for (k = 0; k < 256; k++) { /* m[k][1] = float(k - 192) for the elements in range */
        for (c = 0; c < 9; c++) {
            float got = m[(48 * k + 16 * (c / 3) + 4 * (c % 3)) / 4];
            float want = k < 220 ? rb_mat((int)k, (int)(c / 3), (int)(c % 3)) : -7.0f;
            if (k >= 192 && k < 220 && c % 3 == 1)
                want = (float)(k - 192);
            EXPECT(got == want, "M element %u entry %u: %g, want %g", k, c, (double)got, (double)want);
        }
    }
    CHECK(bad == 0);
    mt_buffer_free(&data);
    mt_buffer_free(&ub);
    mt_buffer_free(&out);
    mt_buffer_free(&wb);
    mt_buffer_free(&mb);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_robust_buffers(void)
{
    check_robust_buffers(spv_robust_buf, PVK_ARRAY_SIZE(spv_robust_buf));
}

static void test_robust_buffers_opt(void)
{
    check_robust_buffers(spv_robust_buf_opt, PVK_ARRAY_SIZE(spv_robust_buf_opt));
}

static struct mt_binding bind_image(uint32_t binding, id texture)
{
    struct mt_binding b;
    memset(&b, 0, sizeof(b));
    b.binding = binding;
    b.texture = texture;
    return b;
}

static void test_robust_images(void)
{
    struct pvk_msl_options opt = robust_options();
    struct pvk_msl_result res;
    struct mt_buffer out, tb, tbw, ubb;
    struct mt_binding b[9];
    id pso, img, imgw, imga, tex, tbuf, tbufw, ubuf, imgarr;
    uint32_t px[16], *o, i, x, y, k, l, a;
    float texels[4 * 4 * 4], arr[2][16 * 4];

    MT_BUILD(spv_robust_img, &opt, res, pso);
    img = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Uint, 4, 4, 1, 1, 1, 1);
    imgw = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Uint, 4, 4, 1, 1, 1, 1);
    imga = mt_texture(PVK_MTLTextureType2D, PVK_MTLPixelFormatR32Uint, 4, 4, 1, 1, 1, 1);
    for (k = 0; k < 16; k++)
        px[k] = 100 + k;
    mt_upload(img, 0, 0, 4, 4, 1, 4, px);
    memset(px, 0, sizeof(px));
    mt_upload(imgw, 0, 0, 4, 4, 1, 4, px);
    for (k = 0; k < 16; k++)
        px[k] = 1000 + k;
    mt_upload(imga, 0, 0, 4, 4, 1, 4, px);
    tex = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 2, 2, 1);
    for (l = 0; l < 2; l++)
        for (a = 0; a < 2; a++) {
            uint32_t s = 4 >> l;
            for (y = 0; y < s; y++)
                for (x = 0; x < s; x++) {
                    float *t = texels + (y * s + x) * 4;
                    t[0] = (float)(l * 1000 + a * 100 + y * 10 + x);
                    t[1] = t[2] = 0.0f;
                    t[3] = (float)(l + a) + 0.5f;
                }
            mt_upload(tex, l, a, s, s, 1, 16, texels);
        }
    tb = mt_buffer(64 * 4, NULL, 0);
    tbw = mt_buffer(64 * 4, NULL, 0);
    ubb = mt_buffer(64 * 4, NULL, 0);
    for (k = 0; k < 64; k++) {
        ((uint32_t *)tb.data)[k] = 7000 + k;
        ((uint32_t *)tbw.data)[k] = SENTINEL;
        ((uint32_t *)ubb.data)[k] = 9000 + k;
    }
    tbuf = mt_texture_buffer(&tb, PVK_MTLPixelFormatR32Uint, 16, 4);
    tbufw = mt_texture_buffer(&tbw, PVK_MTLPixelFormatR32Uint, 16, 4);
    ubuf = mt_texture_buffer(&ubb, PVK_MTLPixelFormatR32Uint, 16, 4);
    imgarr = mt_texture(PVK_MTLTextureType2DArray, PVK_MTLPixelFormatRGBA32Float, 4, 4, 1, 2, 1, 1);
    for (a = 0; a < 2; a++) {
        for (k = 0; k < 16; k++) {
            arr[a][k * 4] = 0.0f;
            arr[a][k * 4 + 1] = (float)(a * 100 + (k / 4) * 10 + k % 4) + 0.5f;
            arr[a][k * 4 + 2] = arr[a][k * 4 + 3] = 0.0f;
        }
        mt_upload(imgarr, 0, a, 4, 4, 1, 16, arr[a]);
    }
    out = mt_buffer(64 * 8 * 4, NULL, 0);
    b[0] = bind_image(0, img);
    b[1] = bind_image(1, imgw);
    b[2] = bind_image(2, imga);
    b[3] = bind_image(3, tex);
    b[4] = bind_image(4, tbuf);
    b[5] = bind_image(5, ubuf);
    b[6] = bind_image(6, imgarr);
    b[7] = bind(0, 7, &out);
    b[8] = bind_image(8, tbufw);
    CHECK(mt_dispatch(pso, &res, b, 9, NULL, 0, 1, 1, 1));
    o = out.data;
    bad = 0;
    for (i = 0; i < 64; i++) {
        int px_ = (int)(i % 8) - 2, py = (int)(i / 8) - 2, kk = px_ * 8 + py;
        bool in = px_ >= 0 && px_ < 4 && py >= 0 && py < 4;
        int lod = (py + 2) >> 1, layer = (px_ + 2) & 3, fy = py & 3, size = 4 >> (lod < 2 ? lod : 0);
        bool fin = lod < 2 && layer < 2 && px_ >= 0 && px_ < size && fy < size;
        int alayer = px_ + py;
        bool ain = in && alayer >= 0 && alayer < 2;
        uint32_t want[8];
        memset(want, 0, sizeof(want));
        want[0] = in ? 100 + (uint32_t)(py * 4 + px_) : 0;
        want[1] = in ? 1000 + (uint32_t)(py * 4 + px_) : 0;
        want[2] = f2u(fin ? (float)(lod * 1000 + layer * 100 + fy * 10 + px_) : 0.0f);
        want[3] = f2u(fin ? (float)(lod + layer) + 0.5f : 0.0f);
        want[4] = kk >= 0 && kk < 16 ? 7000 + (uint32_t)kk : 0;
        want[5] = kk >= 0 && kk < 16 ? 9000 + (uint32_t)kk : 0;
        want[6] = f2u(ain ? (float)(alayer * 100 + py * 10 + px_) + 0.5f : 0.0f);
        for (k = 0; k < 8; k++)
            EXPECT(o[i * 8 + k] == want[k], "thread %u (%d, %d) result %u: 0x%08x, want 0x%08x", i, px_, py, k, o[i * 8 + k],
                   want[k]);
    }
    mt_download(imgw, 0, 0, 4, 4, 1, 4, px);
    for (k = 0; k < 16; k++) /* written by the thread at (x + 2, y + 2) */
        EXPECT(px[k] == ((k / 4 + 2) * 8 + (k % 4 + 2)) + 1, "written texel %u: %u", k, px[k]);
    mt_download(imga, 0, 0, 4, 4, 1, 4, px);
    for (k = 0; k < 16; k++)
        EXPECT(px[k] == 1001 + k, "atomic texel %u: %u", k, px[k]);
    for (k = 0; k < 64; k++) { /* element k by the thread whose x * 8 + y = k - 6 */
        uint32_t got = ((uint32_t *)tbw.data)[k], want = SENTINEL;
        int kk = (int)k - 6;
        if (k < 16 && kk >= -18 && kk <= 45) {
            int xx = (int)floor((double)(kk + 2) / 8.0), yy = kk - xx * 8;
            want = (uint32_t)((yy + 2) * 8 + (xx + 2)) + 1;
        }
        EXPECT(got == want, "texel buffer element %u: 0x%08x, want 0x%08x", k, got, want);
    }
    CHECK(bad == 0);
    mt_buffer_free(&out);
    mt_buffer_free(&tb);
    mt_buffer_free(&tbw);
    mt_buffer_free(&ubb);
    pvk_release(img);
    pvk_release(imgw);
    pvk_release(imga);
    pvk_release(tex);
    pvk_release(tbuf);
    pvk_release(tbufw);
    pvk_release(ubuf);
    pvk_release(imgarr);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

/* ==========================================================================
 * Integer dot products
 *
 * Packed 4 x 8-bit and vector forms of OpSDot, OpUDot, OpSUDot and their
 * AccSat forms (32, 16 and 8-bit results), with operands at the extremes of
 * their ranges so the accumulations saturate both ways.
 * ========================================================================== */

static int64_t sat64(int64_t v, int64_t lo, int64_t hi)
{
    return v < lo ? lo : v > hi ? hi : v;
}

static int64_t s8(uint32_t v, int k)
{
    return (int8_t)(uint8_t)(v >> (8 * k));
}

static int64_t u8(uint32_t v, int k)
{
    return (uint8_t)(v >> (8 * k));
}

static void check_dot(const uint32_t *words, size_t count)
{
    static const uint32_t edge[8][3] = {
        { 0x80808080u, 0x80808080u, 0x7fffffffu - 1000u }, { 0x80808080u, 0xffffffffu, 0x80000000u + 100u },
        { 0xffffffffu, 0xffffffffu, 0xfffffffeu },         { 0x7f7f7f7fu, 0x80808080u, 0x80000000u },
        { 0x01010101u, 0x01010101u, 0x7fffffffu },         { 0x7f7f7f7fu, 0x7f7f7f7fu, 0x00007fffu },
        { 0x80808080u, 0x7f7f7f7fu, 0xffff8000u },         { 0, 0, 0 },
    };
    struct {
        uint32_t a[64], b[64];
        int32_t acc[64];
    } in;
    struct pvk_msl_result res;
    struct mt_buffer ib, ob;
    struct mt_binding bd[2];
    uint32_t seed = 12345u, i, k, *o;
    id pso;

    for (i = 0; i < 64; i++) {
        if (i < 8) {
            in.a[i] = edge[i][0];
            in.b[i] = edge[i][1];
            in.acc[i] = (int32_t)edge[i][2];
            continue;
        }
        seed = seed * 1664525u + 1013904223u;
        in.a[i] = seed;
        seed = seed * 1664525u + 1013904223u;
        in.b[i] = seed;
        seed = seed * 1664525u + 1013904223u;
        in.acc[i] = (int32_t)seed >> (i % 9);
    }
    pso = build(words, count, NULL, &res);
    REQUIRE(pso);
    ib = mt_buffer(sizeof(in), &in, sizeof(in));
    ob = mt_buffer(64 * 16 * 4, NULL, 0);
    bd[0] = bind(0, 0, &ib);
    bd[1] = bind(0, 1, &ob);
    CHECK(mt_dispatch(pso, &res, bd, 2, NULL, 0, 1, 1, 1));
    o = ob.data;
    bad = 0;
    for (i = 0; i < 64; i++) {
        uint32_t a = in.a[i], b = in.b[i], want[14];
        int32_t acc = in.acc[i];
        int64_t sd = 0, ud = 0, sud = 0, d16 = 0, h8 = 0, l8 = 0, x3 = 0;
        uint64_t u3 = 0;
        int64_t ia[3], ib3[3], sx[3];
        uint64_t ua[3], ub3[3];
        for (k = 0; k < 4; k++) {
            sd += s8(a, (int)k) * s8(b, (int)k);
            ud += u8(a, (int)k) * u8(b, (int)k);
            sud += s8(a, (int)k) * u8(b, (int)k);
            h8 += (s8(a, (int)k) >> 1) * (s8(b, (int)k) >> 1);
            l8 += (int64_t)(u8(a, (int)k) & 7) * (int64_t)(u8(b, (int)k) & 7);
        }
        d16 = (int64_t)(int16_t)(a & 0xffff) * (int16_t)(b & 0xffff) + (int64_t)(int16_t)(a >> 16) * (int16_t)(b >> 16);
        ua[0] = a, ua[1] = b, ua[2] = a ^ b;
        ub3[0] = b, ub3[1] = a, ub3[2] = (uint32_t)(a + b);
        for (k = 0; k < 3; k++) {
            ia[k] = (int32_t)ua[k];
            ib3[k] = (int64_t)ub3[k];
            u3 += ua[k] * ub3[k];
            x3 += ia[k] * ib3[k];
            sx[k] = s8(a, (int)k) >> 1;
        }
        want[0] = (uint32_t)sd;
        want[1] = (uint32_t)ud;
        want[2] = (uint32_t)sud;
        want[3] = (uint32_t)sat64(sd + acc, INT32_MIN, INT32_MAX);
        want[4] = (uint32_t)sat64(ud + (int64_t)(uint32_t)acc, 0, UINT32_MAX);
        want[5] = (uint32_t)sat64(sud + acc, INT32_MIN, INT32_MAX);
        want[6] = (uint32_t)sd;
        want[7] = (uint32_t)d16;
        want[8] = (uint32_t)u3;
        want[9] = (uint32_t)x3;
        want[10] = (uint32_t)(int32_t)sat64(h8 + (int16_t)(uint16_t)acc, INT16_MIN, INT16_MAX);
        want[11] = (uint32_t)sat64(l8 + (uint8_t)acc, 0, 255);
        want[12] = (uint32_t)sat64(sx[0] * (b & 0xffff) + sx[1] * (a & 0xffff) + sx[2] * 7 + acc, INT32_MIN, INT32_MAX);
        want[13] = (uint32_t)sat64((int64_t)(a >> 17) * (b >> 17) + (int64_t)((int32_t)a >> 20) * ((int32_t)b >> 20) + acc,
                                   INT32_MIN, INT32_MAX);
        for (k = 0; k < 14; k++)
            EXPECT(o[i * 16 + k] == want[k], "thread %u (a 0x%08x, b 0x%08x, acc %d) result %u: 0x%08x, want 0x%08x", i, a,
                   b, acc, k, o[i * 16 + k], want[k]);
    }
    CHECK(bad == 0);
    mt_buffer_free(&ib);
    mt_buffer_free(&ob);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

static void test_integer_dot_product(void)
{
    check_dot(spv_dot, PVK_ARRAY_SIZE(spv_dot));
}

static void test_integer_dot_product_opt(void)
{
    check_dot(spv_dot_opt, PVK_ARRAY_SIZE(spv_dot_opt));
}

/* ==========================================================================
 * Workgroup memory initialization
 *
 * A kernel first fills threadgroup memory with garbage; then each workgroup
 * of the test reads its zero-initialized variables (an array, a vector, a
 * struct) before writing them, and earlier workgroups' writes must not show.
 * (M4 Max starts every threadgroup's memory zeroed anyway, which Metal does
 * not document: the translator writes the initializers.)
 * ========================================================================== */

static const char garbage_msl[] =
    "#include <metal_stdlib>\nusing namespace metal;\n"
    "kernel void garbage(uint t [[thread_index_in_threadgroup]])\n"
    "{\n"
    "    threadgroup uint g[8192];\n"
    "    for (uint i = t; i < 8192u; i += 256u)\n"
    "        g[i] = 0xa5a5a5a5u ^ i;\n"
    "    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
    "    if (g[(t * 7u) & 8191u] == 1u)\n"
    "        g[0] = 2u;\n"
    "}\n";

static void fill_threadgroup_memory(void)
{
    struct pvk_msl_result fake;
    id pso;
    memset(&fake, 0, sizeof(fake));
    fake.msl = (char *)garbage_msl;
    snprintf(fake.entry_point, sizeof(fake.entry_point), "garbage");
    fake.workgroup_size[0] = 256;
    fake.workgroup_size[1] = fake.workgroup_size[2] = 1;
    pso = mt_pipeline(&fake);
    if (pso)
        mt_dispatch(pso, &fake, NULL, 0, NULL, 0, 512, 1, 1);
    pvk_release(pso);
}

static void check_workgroup_zero(const uint32_t *words, size_t count)
{
    struct pvk_msl_result res;
    struct mt_buffer out;
    struct mt_binding b;
    uint32_t i, groups = 256, *o;
    id pso = build(words, count, NULL, &res);
    REQUIRE(pso);
    out = mt_buffer(groups * 64 * 4, NULL, 0);
    fill_u32(out.data, 0, groups * 64 * 4, SENTINEL);
    b = bind(0, 0, &out);
    fill_threadgroup_memory();
    CHECK(mt_dispatch(pso, &res, &b, 1, NULL, 0, groups, 1, 1));
    o = out.data;
    bad = 0;
    for (i = 0; i < groups * 64; i++)
        EXPECT(o[i] == 0, "invocation %u read %u (0x%08x) from initialized workgroup memory", i, o[i], o[i]);
    CHECK(bad == 0);
    mt_buffer_free(&out);
    pvk_release(pso);
    pvk_msl_result_free(&res);
}

